using GMConverter.SDK.Audio;
using GMConverter.SDK.Exporters;
using GMConverter.SDK.Options;
using GMConverter.SourceEngine.Audio;
using GMConverter.SourceEngine.Exporters;

namespace GMConverter.SourceEngine.Tests;

public sealed class WAVExporterTests
{
    [Fact]
    public void GarrysModGetsSoundAddCallsNamedAfterTheEvents()
    {
        var output = Export(Footsteps(), "garrysmod");

        var lua = File.ReadAllText(Path.Join(output, "lua", "autorun", "b1_sounds.lua"));
        Assert.Equal(
            """
            -- Generated by GMConverter.

            sound.Add({
            	name = "Play_FS_B1",
            	channel = CHAN_BODY,
            	volume = { 0.5, 1 },
            	level = 75,
            	pitch = { 95, 105 },
            	sound = {
            		"gmconverter/b1/step_a.wav",
            		"gmconverter/b1/step_b.wav",
            		"gmconverter/b1/step_b.wav",
            	},
            })

            """.ReplaceLineEndings("\n"),
            lua);
        Assert.False(Directory.Exists(Path.Join(output, "scripts")));
    }

    [Fact]
    public void OtherSourceGamesGetASoundScript()
    {
        var output = Export(Footsteps(), "source");

        var script = File.ReadAllText(Path.Join(output, "scripts", "b1_sounds.txt"));
        Assert.Equal(
            """
            // Generated by GMConverter.

            "Play_FS_B1"
            {
            	"channel"	"CHAN_BODY"
            	"volume"	"0.5, 1"
            	"pitch"	"95, 105"
            	"soundlevel"	"SNDLVL_75dB"
            	"rndwave"
            	{
            		"wave"	"gmconverter/b1/step_a.wav"
            		"wave"	"gmconverter/b1/step_b.wav"
            		"wave"	"gmconverter/b1/step_b.wav"
            	}
            }

            """.ReplaceLineEndings("\n"),
            script);
    }

    [Fact]
    public void PositionalClipsBecomeMonoAtASourceRate()
    {
        var output = Export(Footsteps(), "garrysmod");

        var step = WaveFile.Read(Path.Join(output, "sound", "gmconverter", "b1", "step_a.wav"));
        Assert.Equal(1, step.Channels);
        Assert.Equal(44100, step.SampleRate);
        Assert.Equal(4410, step.FrameCount);
    }

    [Fact]
    public void ClipsOfLoopingEventsLoopAndUnpositionedOnesKeepTheirChannels()
    {
        var music = new SoundClip("Music", 44100, 2, new float[200]);
        var sound = new Sound("Theme", [music], [new SoundEvent("Play_Theme", [new SoundEventEntry("Music")]) { Loops = true }]);

        var output = Export(sound, "garrysmod");

        var written = WaveFile.Read(Path.Join(output, "sound", "gmconverter", "theme", "music.wav"));
        Assert.Equal(2, written.Channels);
        Assert.Equal(new SoundLoop(0), written.Loop);
        Assert.Contains("level = 0,", File.ReadAllText(Path.Join(output, "lua", "autorun", "theme_sounds.lua")));
    }

    [Fact]
    public void AClipWithoutEventsIsOnlyAWave()
    {
        var sound = new Sound("Beep", [new SoundClip("Beep", 22050, 1, new float[10])], []);
        var output = Export(sound, "garrysmod");

        Assert.True(File.Exists(Path.Join(output, "sound", "gmconverter", "beep", "beep.wav")));
        Assert.False(Directory.Exists(Path.Join(output, "lua")));
    }

    [Theory]
    [InlineData(null, 0)]
    [InlineData(31.75f, 75)]
    [InlineData(1f, 60)]
    [InlineData(1000f, 140)]
    public void AttenuationDistanceBecomesTheLevelThatCarriesAsFar(float? meters, int level)
    {
        Assert.Equal(level, SourceSoundDefinitions.SoundLevel(meters));
    }

    private static Sound Footsteps()
    {
        // Two 0.1 s stereo clips at 48 kHz; the second is picked twice as often.
        SoundClip Step(string name) => new(name, 48000, 2, new float[4800 * 2]);
        var footsteps = new SoundEvent("Play_FS_B1", [new SoundEventEntry("Step_A"), new SoundEventEntry("Step_B", 2f)])
        {
            Volume = new SoundRange(0.5f, 1f),
            Pitch = new SoundRange(0.95f, 1.05f),
            AttenuationMeters = 31.75f,
            Category = SoundCategory.Footstep,
        };
        return new Sound("B1", [Step("Step_A"), Step("Step_B")], [footsteps]);
    }

    private static string Export(Sound sound, string target)
    {
        var output = Path.Join(Path.GetTempPath(), "GMConverter.SourceEngine.Tests", Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(output);
        new WAVExporter().Export(sound, new ExportContext(output, sound.Name, OptionValues.Empty) { TargetGameId = target });
        return output;
    }
}
